#!/usr/bin/env bash
# Fixes a real port collision found on the actual Windows deployment
# (Ewan): the Kiosk Application's run.py defaulted to port 8420, which is
# ALREADY owned by a separate, pre-existing product on the same machine -
# StockTool Kiosk (confirmed live: curl http://127.0.0.1:8420/ returned
# {"service":"StockTool Kiosk (local)", ...}). The new kiosk-app process
# lost the bind and died silently (ProcessSupervisor pipes child
# stdout/stderr to DEVNULL), leaving the health check hitting StockTool
# Kiosk's own unrelated routes and getting 404s forever.
#
# Fixed by moving the Kiosk Application to port 8421 (overridable via
# OPSLAB_KIOSK_PORT so a future collision is a one-line env var fix, not
# another release build) and updating agent/update_manager.py's
# auto-defaulted kiosk_health_check_url to match. This is kiosk-app
# v1.0.1 - the package itself, uploaded as a new release below.
#
# IMPORTANT - Ewan (and anywhere else v1.0.0 already got auto-configured)
# needs a MANUAL follow-up after this: the agent's already-persisted
# kiosk_health_check_url still says 8420 (the once-only auto-default logic
# won't fire again now that something is configured) - push v1.0.1 to it,
# then use "Configure what starts the kiosk process" on its instance page
# to resupply the SAME start command with the health check URL corrected
# to http://127.0.0.1:8421/health. Brand-new future enrollments don't need
# this - they get the corrected default from a never-configured agent.
#
# Verified: kiosk app boots and serves a real 200 from /health on 8421 in
# this session; confirmed nothing is emitted on 8420 from this app.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ (update_manager.py port fix) into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "8421" "$TMP_EXTRACT/agent/update_manager.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 10 app.log

echo ""
echo "==> Uploading kiosk-app v1.0.1 (port fix)"
TMP_KIOSK="$(mktemp -d)/kiosk-app-v1.0.1.zip"
mkdir -p "$(dirname "$TMP_KIOSK")"
base64 -d > "$TMP_KIOSK" << 'KIOSK_ZIP_EOF_MARKER'

KIOSK_ZIP_EOF_MARKER

set +e
UPLOAD_OUTPUT="$(FLASK_APP=run.py python -m flask upload-release "$TMP_KIOSK" 1.0.1 --notes "Port fix: moved off 8420 (collided with StockTool Kiosk) to 8421" 2>&1)"
UPLOAD_STATUS=$?
set -e
echo "$UPLOAD_OUTPUT"
rm -f "$TMP_KIOSK"

if [ $UPLOAD_STATUS -ne 0 ] && ! echo "$UPLOAD_OUTPUT" | grep -q "already exists"; then
    echo "    ERROR: release upload failed - see output above."
    exit 1
fi

echo ""
echo "Done. New enrollments from here on get the fixed port automatically."
echo ""
echo "For Ewan specifically (already on v1.0.0, port 8420):"
echo "  1. Open Ewan's instance page -> Updates -> push v1.0.1 now."
echo "  2. Once it's installed, open 'Configure what starts the kiosk process' and"
echo "     resupply:"
echo "       Start command:        \"C:\Program Files\OpsLabAgent\python\python.exe\" run.py"
echo "       Working directory:    C:\Program Files\OpsLabAgent\app"
echo "       Health check URL:     http://127.0.0.1:8421/health"
echo "     Save & apply - this corrects the stored health check URL and restarts it."
